// The conversion limits of round 5 (port of curecodejp 6.1.2) on the files of the issue
// "E2E limits" (generated by test/e2e/seed.rb): the limits on the settings page; an archive
// bomb and an archive of too many entries refused with 413; emails too large, too deeply
// nested or of too many parts refused with their reason; a converter program that hangs
// (test/e2e/bin/pandoc) stopped at the time limit and not run again while its failure is
// remembered; reload and unsafe for administrators only; the cache rake task; a hostile vCard.
import { e2e } from '../../.codex/e2e/lib.mjs';
import { execSync } from 'node:child_process';
import fs from 'node:fs';

const REDMINE = process.env.REDMINE_DIR;
const STORAGE = `${REDMINE}/tmp/more_previews`;
const t = await e2e('limits');
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;');
async function table(title, intro, rows) {
  await t.page.setContent(`<style>body{font:14px sans-serif;margin:24px}td,th{border:1px solid #ccc;padding:4px 8px;text-align:left}</style>` +
    `<h2>${esc(title)}</h2><p>${esc(intro)}</p><table><tr><th>${rows[0].map(esc).join('</th><th>')}</th></tr>` +
    rows.slice(1).map(r => `<tr><td>${r.map(esc).join('</td><td>')}</td></tr>`).join('') + '</table>');
}
async function get(path) {
  const started = Date.now();
  const r = await t.page.request.get(t.BASE + path, { timeout: 120000 });
  return { status: r.status(), body: await r.text(), etag: r.headers()['etag'] || '', seconds: ((Date.now() - started) / 1000).toFixed(1) };
}

await t.login('admin');
const att = {};
const limitsIssue = (await (await t.page.request.get(`${t.BASE}/issues.json?project_id=e2e-project&subject=E2E%20limits`, { headers: apiKey() })).json()).issues[0];
for (const a of (await (await t.page.request.get(`${t.BASE}/issues/${limitsIssue.id}.json?include=attachments`, { headers: apiKey() })).json()).issue.attachments) att[a.filename] = a.id;
const samples = (await (await t.page.request.get(`${t.BASE}/issues.json?project_id=e2e-project&subject=E2E%20previews`, { headers: apiKey() })).json()).issues[0];
for (const a of (await (await t.page.request.get(`${t.BASE}/issues/${samples.id}.json?include=attachments`, { headers: apiKey() })).json()).issue.attachments) att[a.filename] = a.id;

// --- the limits on the settings page
await t.go('/settings/plugin/redmine_more_previews');
const legend = t.page.locator('legend', { hasText: 'Conversion limits' });
if (!(await legend.count())) t.problems.push('settings: no "Conversion limits" fieldset');
for (const [field, want] of [['conversion_timeout', '10'], ['lock_timeout', '5'], ['max_conversions', '2'], ['max_repository_file', '50'],
                             ['max_output', '100'], ['max_cache', '10240'], ['failure_ttl', '10']]) {
  const v = await t.page.inputValue(`input[name="settings[${field}]"]`).catch(() => null);
  if (v !== want) t.problems.push(`settings: ${field} is ${v}, expected ${want}`);
}
await t.page.click('a[onclick*="help_redmine_more_previews_limits"]');
await legend.scrollIntoViewIfNeeded();
await t.shot('settings', 'Settings > Plugins > More previews: the conversion limits (time limit 10 s for the e2e run, the others at their defaults) with the help text opened', { full: false });

// --- archives (as the manager)
await t.login('manager');
await t.go(`/attachments/${att['bomb.zip']}`);
await t.page.waitForTimeout(1500);
await t.page.mouse.move(0, 0);
await t.shot('bomb-listing', 'bomb.zip: the listing works; zeros.bin unpacks to 200 MB (compressed to a few hundred KB)', { full: false });
const archiveRows = [['request', 'HTTP', 'seconds', 'answer']];
for (const [label, path, want] of [
  ['zeros.bin of bomb.zip (200 MiB > 100 MiB per entry)', `/attachments/more_preview/${att['bomb.zip']}/index.html?asset=zeros.bin`, 413],
  ['readme.txt of bomb.zip', `/attachments/more_preview/${att['bomb.zip']}/index.html?asset=readme.txt`, 200],
  ['listing of many.zip (10,001 entries > 10,000)', `/attachments/more_preview/${att['many.zip']}/index.html`, 413],
  ['listing of many.zip again', `/attachments/more_preview/${att['many.zip']}/index.html`, 413],
]) {
  const r = await get(path);
  archiveRows.push([label, r.status, r.seconds, r.body.slice(0, 60)]);
  if (r.status !== want) t.problems.push(`${label}: HTTP ${r.status}, expected ${want}`);
}
await table('Archives beyond the limits, as manager', 'Zippy refuses with 413 before it unpacks or lists more than its limits.', archiveRows);
await t.shot('archives-413', 'An entry unpacking beyond 100 MiB and a zip of more than 10,000 entries are answered with 413 "The file is too large to be previewed."', { full: false });
await t.go(`/attachments/${att['many.zip']}`, { allow: { requests: ['413 '] } });
await t.page.waitForTimeout(1500);
await t.page.mouse.move(0, 0);
await t.shot('many-page', 'The page of many.zip: the preview frame (an <object> with embedding 0) stays empty, the browser shows no error body of a 413 there (as for 404 and 503)', { full: false });

// --- emails (Cliff's limits: max_size lowered to 1 MiB for the e2e, the others at their defaults)
const mailRows = [['email', 'HTTP', 'seconds', 'preview']];
for (const [name, reason] of [['large.eml', 'larger than 1 MiB'], ['nested.eml', 'more than 100 nested multipart parts'], ['parts.eml', 'more than 1000 parts']]) {
  const r = await get(`/attachments/more_preview/${att[name]}/index.html`);
  mailRows.push([name, r.status, r.seconds, r.body.slice(0, 80)]);
  // round 6 (curecodejp 6b27fe7): 413, the reason is its body
  if (r.status !== 413) t.problems.push(`${name}: HTTP ${r.status}, expected 413`);
  if (!r.body.includes(reason)) t.problems.push(`${name}: answer lacks "${reason}": ${r.body.slice(0, 200)}`);
  if (/\.rb:\d+|backtrace/.test(r.body)) t.problems.push(`${name}: the preview shows a backtrace`);
}
await table('Emails beyond Cliff\'s limits, as manager', 'Cliff refuses before Mail parses the email (size, parts) or before it walks the parts (nesting): HTTP 413 with the reason as its body, without a backtrace (round 6).', mailRows);
await t.shot('emails-refused', 'An email above the size limit, one nested 150 levels deep and one of 1,001 parts are refused with 413 and their reason', { full: false });
// the failure is remembered: a fresh one, so that the page converts and says why
execSync(`find ${STORAGE}/failures -type f -delete`);
await t.go(`/attachments/${att['nested.eml']}`, { allow: { requests: ['413 '] } });
await t.page.waitForTimeout(1500);
await t.page.mouse.move(0, 0);
const warning = (await t.page.locator('#content p.warning').textContent().catch(() => '')) || '';
if (!warning.includes('more than 100 nested multipart parts')) t.problems.push(`nested.eml page: no warning with the reason ("${warning}")`);
await t.shot('nested-page', 'The page of nested.eml: a warning above the empty preview frame (413) says why the email is not previewed', { full: false });

// --- a converter program that hangs: stopped at the time limit, the failure remembered
const pidFile = `${REDMINE}/tmp/e2e-hang.pid`;
fs.rmSync(pidFile, { force: true });
const hangRows = [['request', 'HTTP', 'seconds', 'pandoc stand-in']];
const first = await get(`/attachments/more_preview/${att['hang.md']}/index.html`);
const pid = fs.existsSync(pidFile) ? fs.readFileSync(pidFile, 'utf8').trim() : '';
const alive = p => { try { return !/^State:\s+Z/m.test(fs.readFileSync(`/proc/${p}/status`, 'utf8')); } catch { return false; } };
hangRows.push(['first request', first.status, first.seconds, pid ? `pid ${pid} started, ${alive(pid) ? 'STILL RUNNING' : 'stopped'}` : 'not started']);
if (!pid) t.problems.push('hang: the pandoc stand-in did not run (is test/e2e/bin in the server PATH?)');
if (pid && alive(pid)) t.problems.push(`hang: pandoc stand-in ${pid} still runs after the request`);
if (first.status !== 404 || first.seconds < 9 || first.seconds > 30) t.problems.push(`hang: first request HTTP ${first.status} after ${first.seconds} s, expected 404 after about 10 s`);
fs.rmSync(pidFile, { force: true });
const again = await get(`/attachments/more_preview/${att['hang.md']}/index.html`);
hangRows.push(['same request again', again.status, again.seconds, fs.existsSync(pidFile) ? 'STARTED AGAIN' : 'not started (failure remembered)']);
if (again.status !== 404 || again.seconds > 2 || fs.existsSync(pidFile)) t.problems.push(`hang: second request HTTP ${again.status} after ${again.seconds} s${fs.existsSync(pidFile) ? ', converted again' : ''}`);
const other = await get(`/attachments/more_preview/${att['sample.md']}/index.html`);
hangRows.push(['sample.md meanwhile', other.status, other.seconds, 'real pandoc']);
if (other.status !== 200) t.problems.push(`hang: sample.md HTTP ${other.status}`);
await table('A converter program that hangs, as manager', 'hang.md makes the pandoc stand-in (test/e2e/bin/pandoc) sleep; the time limit is 10 s for the e2e run.', hangRows);
await t.shot('hang', 'The hanging conversion is stopped with its process after the 10 s time limit (404); the same request is answered at once afterwards, without starting pandoc again', { full: false });

// --- reload and unsafe: administrators only
const mail = `/attachments/more_preview/${att['sample.eml']}/index.html`;
const reloadRows = [['user', 'plain', '?reload=1', '?unsafe=1', 'converted again?']];
await t.login('admin');
const base = await get(mail);
await t.page.waitForTimeout(1100);
for (const user of ['manager', 'reporter', 'outsider', 'admin']) {
  await t.login(user);
  const plain = await get(mail), reload = await get(`${mail}?reload=1`), unsafe = await get(`${mail}?unsafe=1`);
  const again = reload.etag && reload.etag !== base.etag;
  reloadRows.push([user, plain.status, `${reload.status} ${reload.etag.slice(0, 14)}`, `${unsafe.status} ${unsafe.etag.slice(0, 14) || '(no cache)'}`, again ? 'yes' : 'no']);
  if (user === 'admin' && !again) t.problems.push('reload: an administrator\'s reload did not convert again');
  if (user !== 'admin' && again) t.problems.push(`reload: ${user}'s reload converted again`);
  if (user === 'manager' && (plain.status !== 200 || unsafe.etag !== base.etag)) t.problems.push(`unsafe: manager's unsafe was not served from the cache (${unsafe.status} ${unsafe.etag})`);
}
await table('reload and unsafe per user (sample.eml)', `ETag of the cached preview before: ${base.etag}. A new ETag means the preview was converted again.`, reloadRows);
await t.shot('reload-users', 'reload and unsafe take effect for the administrator only; for manager, reporter and outsider the request is served as without them', { full: false });
await t.go(`/attachments/${att['sample.eml']}`);
if (!(await t.page.locator('#content a.icon-reload').count()) || !(await t.page.locator('#content a.icon-warning').count())) t.problems.push('admin: Update or unsafe link missing');
await t.page.waitForTimeout(1500);
await t.shot('links-admin', 'As administrator the email page offers "Update" and Cliff\'s unsafe reload', { full: false });
await t.login('manager');
await t.go(`/attachments/${att['sample.eml']}`);
if (await t.page.locator('#content a.icon-reload, #content a.icon-warning').count()) t.problems.push('manager: Update or unsafe link shown');
await t.page.waitForTimeout(1500);
await t.shot('links-manager', 'As manager (every permission of the project) the same page has neither link', { full: false });

// --- the cache rake task
const markers = execSync(`find ${STORAGE}/attachments/${att['sample.md']} -maxdepth 1 -name '*.converter'`).toString().trim().split('\n').filter(Boolean);
for (const m of markers) execSync(`touch -d '40 days ago' '${m}'`);
const out = execSync('bundle exec rake redmine_more_previews:cache:clean DAYS=30', { cwd: REDMINE, env: { ...process.env, RAILS_ENV: 'production' } }).toString().trim();
const gone = markers.every(m => !fs.existsSync(m.replace(/\.converter$/, '')));
const after = await get(`/attachments/more_preview/${att['sample.md']}/index.html`);
if (!/^[1-9]\d* cached previews removed$/m.test(out) || !gone) t.problems.push(`cache:clean: "${out}", removed: ${gone}`);
if (after.status !== 200) t.problems.push(`cache:clean: sample.md afterwards HTTP ${after.status}`);
await table('rake redmine_more_previews:cache:clean DAYS=30', 'The marker of the cached preview of sample.md was set 40 days back, then the task ran in production mode.',
  [['step', 'result'], ['aged markers', markers.map(m => m.replace(STORAGE, 'tmp/more_previews')).join(', ')], ['task output', out],
   ['preview directory removed', gone ? 'yes' : 'NO'], ['sample.md preview afterwards', `HTTP ${after.status} (converted again)`]]);
await t.shot('cache-clean', 'The cache rake task removes previews cached more than DAYS days ago; the next request converts the file again', { full: false });

// --- a hostile vCard
const vcf = await get(`/attachments/more_preview/${att['hostile.vcf']}/index.html`);
for (const [bad, what] of [['<b>bold</b>', 'markup of the name'], ['<img src=x onerror', 'an event handler'], ['href="javascript:', 'a javascript: link'],
                           ['evil', 'the injected GEO path in a link'], ['file:///etc/passwd"', 'a file: image'], ['root:', 'a server file']]) {
  const hit = bad === 'evil' ? /href="[^"]*evil/.test(vcf.body) : vcf.body.includes(bad);
  if (hit) t.problems.push(`hostile.vcf: ${what} in the preview`);
}
if (!vcf.body.includes('&lt;b&gt;bold&lt;/b&gt;')) t.problems.push('hostile.vcf: the name is not shown as text');
await t.go(`/attachments/${att['hostile.vcf']}`, { allow: { js: ['has been blocked by CORS policy'] } });
await t.page.waitForTimeout(1500);
await t.page.mouse.move(0, 0);
await t.shot('hostile-vcard', 'hostile.vcf: the name with HTML is shown as text, the javascript: URL and IMPP are text, the GEO value with an injected path is no map link, the file: photo is not rendered', { full: false });
await t.done();

// lookups through the manager's API key (test/e2e/seed.rb): a plugin may restrict issue data for a session
function apiKey() {
  return { 'X-Redmine-API-Key': fs.readFileSync(`${REDMINE}/tmp/e2e-manager-api-key`, 'utf8').trim() };
}
